<?php require 'config.php';require 'includes/functions.php';$s=$pdo->prepare("SELECT p.*,c.name category_name FROM products p JOIN categories c ON c.id=p.category_id WHERE p.id=? AND p.active=1");$s->execute([(int)($_GET['id']??0)]);$p=$s->fetch();if(!$p){http_response_code(404);exit('Product not found');}$r=$pdo->prepare("SELECT r.*,u.name FROM reviews r JOIN users u ON u.id=r.user_id WHERE r.product_id=? ORDER BY r.created_at DESC");$r->execute([$p['id']]);$reviews=$r->fetchAll();$title=$p['name'];require 'includes/header.php';?><div class="detail"><div class="detail-image"><img src="<?=e($p['image_url'])?>" alt="<?=e($p['name'])?>"></div><div class="detail-copy"><span class="eyebrow"><?=e($p['category_name'])?> / <?=e($p['subcategory'])?></span><h1><?=e($p['name'])?></h1><h2><?=money($p['price'])?></h2><p><?=e($p['description'])?></p><p class="muted"><?=((int)$p['stock']>0)?'In stock':'Currently unavailable'?> · <?=e($p['size_guide'])?></p><?php if($p['stock']>0):?><form method="post" action="cart.php"><?=csrf_field()?><input type="hidden" name="action" value="add"><input type="hidden" name="product_id" value="<?=$p['id']?>"><label>Quantity<input type="number" name="quantity" value="1" min="1" max="<?=$p['stock']?>"></label><button class="button dark">Add to bag</button></form><?php endif;?><form method="post" action="wishlist.php"><?=csrf_field()?><input type="hidden" name="product_id" value="<?=$p['id']?>"><button class="button outline">♡ Add to wishlist</button></form></div></div><section class="reviews"><h2>Customer reviews</h2><?php foreach($reviews as $rv):?><p><b><?=e($rv['name'])?></b> · <?=str_repeat('★',(int)$rv['rating'])?><br><?=e($rv['comment'])?></p><?php endforeach;?><?php if(current_user()):?><form method="post" action="review.php"><?=csrf_field()?><input type="hidden" name="product_id" value="<?=$p['id']?>"><label>Your rating<select name="rating"><option value="5">5 - Excellent</option><option value="4">4 - Very good</option><option value="3">3 - Good</option><option value="2">2 - Fair</option><option value="1">1 - Poor</option></select></label><textarea name="comment" maxlength="1000" placeholder="Share your thoughts"></textarea><button class="button">Submit review</button></form><?php else:?><p><a href="login.php">Sign in</a> to leave a review.</p><?php endif;?></section><?php require 'includes/footer.php';?>